function scopeSections(items){return [...new Set(items.map(x=>String(x.p.id)))].flatMap(id=>[false,true].map(material=>({label:material?'Materials':'Labor',lines:items.filter(x=>String(x.p.id)===id&&!!x.po.material===material)})).filter(section=>section.lines.length));}
function approvedEntries(){return entries().filter(x=>x.po.status==='Approved');}
function entry(k){return entries().find(x=>x.key===k);}
function cfg(x){if(x.stage)return {sub:x.stage.kind==='Sub',subPct:x.po.builderCost?100*(x.stage.budgetCents/100)/x.po.builderCost:0,company:x.stage.company||'',splits:clone(x.stage.crew||[])};const c=doc?.configs?.[x.key]||{sub:!!x.po.subs,subPct:x.po.subPct??(x.po.material?60:75),company:x.po.subId||'',splits:clone(x.po.splits||[])};return x.po.material?{...c,sub:true}:c;}
function description(x){if(typeof x.po.description==='string')return x.po.description;const rows=(x.p.estimate||[]).filter(r=>x.po.sourceEstimateKey?estimateRowSourceKey(r)===x.po.sourceEstimateKey:(String(r.title||r.line||'')===getPOBaseTitle(x.po)&&String(r.parentGroup||'').toLowerCase()===String(x.po.parentGroup||'').toLowerCase()&&estimatePOEligible(r)));return rows.length===1?rows[0].description||'':'';}
function alloc(x){if(x.stage)return stageAlloc(x);const c=cfg(x),base=Math.round(cents(x.po.builderCost)*Number(c.housePct??60)/100);return c.sub?[{person:doc?.companies?.[c.company]?.name||'Unassigned supplier / sub',companyId:c.company,pct:Number(c.subPct),amount:Math.round(cents(x.po.builderCost)*Number(c.subPct)/100)}]:(c.splits||[]).filter(s=>s.name&&Number(s.pct)>0).map(s=>({person:s.name,pct:Number(s.pct),amount:Math.round(base*Number(s.pct)/100)}));}
function paid(workId,name){return Object.values(doc?.payments||{}).filter(p=>!p.voided).flatMap(p=>p.lines).filter(l=>l.workId===workId&&l.person===name).reduce((s,l)=>s+l.amount,0);}
const subSelected=new Set();
function incomplete(id){return !!doc?.lifecycle?.[id]?.incomplete||!!(doc?.work?.[id]?.workState==='In progress'&&!doc?.lifecycle?.[id]?.completedDate);}
function effectiveWork(id){const w=doc?.work?.[id],x=entry(id);return w?{...w,line:x?.stage?x.stage.title:w.line,builderCost:x?.stage?cents(x.po.builderCost):w.builderCost,description:x?description(x):w.description,completedDate:doc?.lifecycle?.[id]?.completedDate||w.completedDate}:null;}
function billedAmount(d,id,a){const w=d.work[id],life=d.lifecycle?.[id];if(!w||life?.incomplete)return 0;if(life?.completedDate||w.completedDate)return a.amount;return Math.min(a.amount,Math.max(0,Number(life?.partialComplete?.amounts?.[a.person]||0)));}
function hasBill(id){return !!doc?.work[id]&&doc.work[id].allocations.some(a=>billedAmount(doc,id,a)>0);}
function billWork(id){const w=effectiveWork(id);if(!w)return null;return {...w,partialComplete:incomplete(id),completedDate:w.completedDate||doc.lifecycle?.[id]?.partialComplete?.date,allocations:w.allocations.map(a=>({...a,agreedAmount:a.amount,amount:billedAmount(doc,id,a)})).filter(a=>a.amount>0)};}
function rows(){return Object.keys(doc?.work||{}).filter(id=>entry(id)?.po.status==='Approved'&&hasBill(id)).flatMap(workId=>{const w=billWork(workId);return w.allocations.map(a=>({...a,workId,w,balance:a.amount-paid(workId,a.person)}));});}
// An advance locks the agreed allocation, without inventing a completion date.
function payoutSnapshot(x){return {...(x.stage?{stageId:x.stage.id,parentKey:x.parentKey}:{}),jobId:String(x.p.id),job:x.p.name,po:String(x.po.id),line:getPOBaseTitle(x.po),description:description(x),builderCost:cents(x.po.builderCost),kind:cfg(x).sub?'Sub':'In-house',workState:'In progress',status:'Approved',allocations:alloc(x),recordedAt:new Date().toISOString(),recordedBy:state.currentUser};}
function payableRows(){return rows();}
function paymentStatus(amount,balance){return balance<=0?'Paid in full':balance<amount?'Partially paid':'Unpaid';}
function progressPaymentHTML(x){const w=effectiveWork(x.key)||payoutSnapshot(x);const remaining=w.allocations.some(a=>a.amount>Math.max(billedAmount(doc,x.key,a),paid(x.key,a.person)));return w.allocations.map(a=>{const already=paid(x.key,a.person),billed=billedAmount(doc,x.key,a);return `<div class="jj-progress-payment"><strong>${E(a.person)} · ${paymentStatus(a.amount,a.amount-already)}</strong><div>Agreed payout ${M(a.amount)} · In Bills ${M(billed)} · Paid ${M(already)} · Unfinished ${M(a.amount-Math.max(billed,already))}</div></div>`;}).join('')+(remaining?action('partial-complete',x.key,'Partially Complete','btn btn-gold'):'')+(hasBill(x.key)?action('view-bill',x.key,'View in Bills'):'');}
function applyPartialCompletion(d,id,name,amount,date){const x=entry(id);if(!x||x.po.status!=='Approved'||!validAlloc(x)||!validDate(date))throw Error('Choose approved work, valid payees, and a completion date.');const w=d.work[id]||payoutSnapshot(x),a=w.allocations.find(a=>a.person===name);if(!a||w.completedDate||d.lifecycle?.[id]?.completedDate)throw Error('This work is already complete or its payee changed.');const used=Object.values(d.payments).filter(p=>!p.voided).flatMap(p=>p.lines).filter(l=>l.workId===id&&l.person===name).reduce((n,l)=>n+l.amount,0),priorAmount=Math.max(billedAmount(d,id,a),used);if(!Number.isSafeInteger(amount)||amount<=0||amount>=a.amount-priorAmount)throw Error('Enter a portion smaller than the unfinished balance, or use Work complete for the full remainder.');d.work[id]||=w;d.lifecycle||={};const life=d.lifecycle[id]||{history:[]},prior=life.incomplete?{amounts:{},date}:(life.partialComplete||{amounts:{},date});d.lifecycle[id]={...life,incomplete:false,partialComplete:{date:prior.date,amounts:{...prior.amounts,[name]:priorAmount+amount}},history:[...(life.history||[]),{action:'partial-complete',person:name,amount,date,at:new Date().toISOString(),by:state.currentUser}]};}
function groupCompletionPlan(d,id,percent){const x=entry(id);if(!x||x.po.status!=='Approved'||!validAlloc(x))throw Error('This P.O. needs valid approved payees.');if(!Number.isFinite(percent)||percent<=0||percent>=100)throw Error('Enter a percentage above 0 and below 100. Use Work complete for 100%.');const w=d.work[id]||payoutSnapshot(x);if(w.completedDate||d.lifecycle?.[id]?.completedDate)throw Error('This work is already complete.');const plan=w.allocations.map(a=>{const used=Object.values(d.payments).filter(p=>!p.voided).flatMap(p=>p.lines).filter(l=>l.workId===id&&l.person===a.person).reduce((n,l)=>n+l.amount,0),prior=Math.max(billedAmount(d,id,a),used),target=Math.round(a.amount*percent/100);if(target<prior)throw Error('This percentage would reduce work already billed or paid. Choose a higher percentage.');if(target>=a.amount)throw Error('This percentage rounds to the full payout for a crew member. Use Work complete.');return {...a,prior,target,additional:target-prior};});if(!plan.some(a=>a.additional>0))throw Error('This completed percentage is already in Bills. Choose a higher percentage.');return plan;}
function applyGroupCompletion(d,id,percent,date){if(!validDate(date))throw Error('Choose a valid completion date.');const plan=groupCompletionPlan(d,id,percent);for(const a of plan)if(a.additional>0)applyPartialCompletion(d,id,a.person,a.additional,date);d.lifecycle[id].partialComplete.percent=percent;}
function partialCompletionForm(id){const x=entry(id);if(!x||x.po.status!=='Approved'||!validAlloc(x))return err(Error('This P.O. needs valid approved payees.'));const w=effectiveWork(id)||payoutSnapshot(x),current=Math.max(0,...w.allocations.map(a=>100*Math.max(billedAmount(doc,id,a),paid(id,a.person))/a.amount)),suggested=Math.min(99.99,Math.max(50,Math.ceil((current+(100-current)/2)*100)/100));modal('Partially Complete',`<form data-partial-complete><h3>${E(w.job)} · ${E(w.po)} · ${E(w.line)}</h3><p>Enter the total percentage of this P.O. completed so far. The same percentage applies to each person's agreed payout, even when their shares differ. Only the increase goes to Bills. No payment is recorded.</p>${paymentDatePicker('date','Completed portion date',today())}<label>Total completed (%)<input type="number" name="completionPercent" min="0.01" max="99.99" step="0.01" value="${suggested}" required></label><div data-completion-preview aria-live="polite"></div><button class="btn btn-gold">Send portion to Bills</button></form>`);const f=dialog.querySelector('[data-partial-complete]');const preview=()=>{const field=f.elements.completionPercent;try{const plan=groupCompletionPlan(doc,id,field.value===''?NaN:Number(field.value));field.setCustomValidity('');f.querySelector('[data-completion-preview]').innerHTML='<div class="table-wrap"><table><tr><th>Employee / Sub</th><th>Agreed payout</th><th>Total in Bills</th><th>Adding now</th><th>Unfinished</th></tr>'+plan.map(a=>`<tr><td>${E(a.person)}</td><td>${M(a.amount)}</td><td>${M(a.target)}</td><td>${M(a.additional)}</td><td>${M(a.amount-a.target)}</td></tr>`).join('')+'</table></div>';}catch(e){field.setCustomValidity(e.message);f.querySelector('[data-completion-preview]').textContent=e.message;}};f.elements.completionPercent.oninput=preview;preview();f.onsubmit=async event=>{event.preventDefault();const percent=Number(f.elements.completionPercent.value),date=f.elements.date.value;if(await change(d=>applyGroupCompletion(d,id,percent,date))){dialog.close();mode=w.kind==='Sub'?'subs':'inhouse';kind=w.kind;job=String(w.jobId);person='';period='All time';render();toast('Completed portion sent to Bills for all assigned payees.');}};}
function applyPaymentRecord(d,payment){
 const seen=new Set();
 for(const line of payment.lines){
  const id=JSON.stringify([line.workId,line.person]);if(seen.has(id))throw Error('Duplicate payment allocation.');seen.add(id);
  const x=entry(line.workId);if(!x||x.po.status!=='Approved'||!validAlloc(x))throw Error('This P.O. must remain approved with valid payees. Refresh and try again.');
  if(d.lifecycle?.[line.workId]?.incomplete)throw Error('This work was reopened for correction. Complete or correct its approval before recording payment.');
  const work=d.work[line.workId]||payoutSnapshot(x),allocation=work.allocations.find(a=>a.person===line.person);
  const used=Object.values(d.payments).filter(p=>!p.voided).flatMap(p=>p.lines).filter(l=>l.workId===line.workId&&l.person===line.person).reduce((sum,l)=>sum+l.amount,0);
  if(!allocation||!Number.isSafeInteger(line.amount)||line.amount<=0||line.amount>billedAmount(d,line.workId,allocation)-used)throw Error('Enter a payment within the remaining balance.');
  if(!d.work[line.workId])d.work[line.workId]=work;
 }
 if(d.payments[payment.id])throw Error('This payment has already been recorded.');
 d.payments[payment.id]=payment;
}

